import XCTest

final class fTrace:XCTestCase {
 @MainActor func testLearningRulesAndPersistence() throws {
 let key="qa."+UUID().uuidString;let store=try XCTUnwrap(UserDefaults(suiteName:key));defer{store.removePersistentDomain(forName:key)}
 let z=bK(store:store);XCTAssertEqual(bV.cities.count,4);XCTAssertEqual(bV.cities.flatMap(\.scenes).count,12)
 for c in bV.cities {XCTAssertEqual(c.quiz.count,4);XCTAssertFalse(z.unlocked(c.scenes[1],c));z.exam(c);XCTAssertNil(z.p.awards[c.id]);for s in c.scenes{for q in s.steps{XCTAssertTrue(q.choices.indices.contains(q.right));XCTAssertFalse(q.why.isEmpty)};z.answer(s.id,false);z.answer(s.id,true);z.finish(s)};XCTAssertNotNil(z.p.awards[c.id]);XCTAssertTrue(z.unlocked(c.scenes[2],c))}
 let midnight=Calendar.current.startOfDay(for:Date());XCTAssertEqual(bV.daily(midnight)?.id,bV.daily(midnight.addingTimeInterval(3600*20))?.id);XCTAssertEqual(z.p.awards.count,4);XCTAssertEqual(bK(store:store).p.done.count,12);XCTAssertEqual(z.p.ledger.values.reduce(0){$0+$1.tries},24);XCTAssertTrue(z.p.daily.contains(bV.day()));let date=z.p.awards[bV.cities[0].id];z.finish(bV.cities[0].scenes[0]);XCTAssertEqual(date,z.p.awards[bV.cities[0].id]);z.clear();XCTAssertTrue(bK(store:store).p.awards.isEmpty)
 }
 func reveal(_ app:XCUIApplication,_ element:XCUIElement){for _ in 0..<7{if element.isHittable{return};app.swipeUp()}}
 func shot(_ name:String){let a=XCTAttachment(screenshot:XCUIApplication().screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
 @MainActor func testJourneyAndParentalGate() throws {
 let app=XCUIApplication();app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();XCTAssertTrue(app.buttons["parents"].waitForExistence(timeout:10));shot("01-city")
 for _ in 0..<3 {if !app.buttons["lesson0"].isHittable{app.swipeUp()}};app.buttons["lesson0"].tap();XCTAssertTrue(app.staticTexts["scenePrompt"].waitForExistence(timeout:5));shot("02-signal")
 let s=bV.cities[0].scenes[0]
 app.buttons["choice\(1-s.steps[0].right)"].tap();XCTAssertTrue(app.staticTexts["Let’s think together"].exists)
 for q in s.steps{let b=app.buttons["choice\(q.right)"];if !b.isHittable{app.swipeUp()};b.tap();let n=app.buttons["nextStep"];if !n.isHittable{app.swipeUp()};n.tap()}
 XCTAssertTrue(app.buttons["finishLesson"].waitForExistence(timeout:4));shot("03-lesson-complete");app.buttons["finishLesson"].tap();app.swipeDown();app.swipeDown();app.buttons["parents"].tap();XCTAssertTrue(app.textFields["gateAnswer"].waitForExistence(timeout:4));app.textFields["gateAnswer"].tap();app.textFields["gateAnswer"].typeText("0");app.buttons["gateSubmit"].tap();XCTAssertTrue(app.textFields["gateAnswer"].exists)
 let question=app.staticTexts["gateQuestion"].label;let nums=question.components(separatedBy:CharacterSet.decimalDigits.inverted).compactMap(Int.init);XCTAssertEqual(nums.count,2);app.textFields["gateAnswer"].tap();app.textFields["gateAnswer"].typeText("\(nums.reduce(0,+))");app.buttons["gateSubmit"].tap();XCTAssertTrue(app.staticTexts["Completed lessons"].waitForExistence(timeout:4));shot("04-parent-report");reveal(app,app.switches["reminderToggle"]);app.switches["reminderToggle"].tap();let alert=app.alerts.firstMatch;if alert.waitForExistence(timeout:4){alert.buttons.element(boundBy:0).tap()};XCTAssertTrue(app.staticTexts["Notifications are disabled. Lessons and progress still work normally."].waitForExistence(timeout:5));shot("09-permission-denied");reveal(app,app.buttons["widgetGallery"]);XCTAssertTrue(app.buttons["widgetGallery"].isHittable);app.buttons["widgetGallery"].tap();shot("10-widgets");app.swipeUp();shot("11-widget-large");app.navigationBars.buttons.element(boundBy:0).tap();app.buttons["Close"].tap()
 app.tabBars.buttons["Signs"].tap();app.buttons["practice.meadow"].tap();shot("05-sign-quiz");for q in bV.cities[0].quiz {app.buttons["quizChoice\(q.right)"].tap();let n=app.buttons["nextQuiz"];if !n.isHittable{app.swipeUp()};n.tap()};XCTAssertTrue(app.buttons["finishQuiz"].exists);app.buttons["finishQuiz"].tap();app.tabBars.buttons["City"].tap();for s in bV.cities[0].scenes.dropFirst(){let idx=bV.cities[0].scenes.firstIndex(where:{$0.id==s.id})!;let b=app.buttons["lesson\(idx)"];reveal(app,b);b.tap();for q in s.steps{reveal(app,app.buttons["choice\(q.right)"]);app.buttons["choice\(q.right)"].tap();reveal(app,app.buttons["nextStep"]);app.buttons["nextStep"].tap()};reveal(app,app.buttons["finishLesson"]);app.buttons["finishLesson"].tap()};app.tabBars.buttons["Certificates"].tap();XCTAssertTrue(app.staticTexts["Learning certificate"].exists);shot("06-certificates");app.terminate();app.launch();XCTAssertTrue(app.buttons["parents"].waitForExistence(timeout:5))
 }
 @MainActor func testLocalizedScreens(){for (lang,locale) in [("de","de_DE"),("pt-BR","pt_BR")]{let a=XCUIApplication();a.launchArguments=["-AppleLanguages","(\(lang))","-AppleLocale",locale];a.launch();XCTAssertTrue(a.buttons["parents"].waitForExistence(timeout:6));shot("locale-"+lang);a.terminate()}}
 @MainActor func testFrenchAndSeasonalLayout() {let app=XCUIApplication();app.launchArguments=["-AppleLanguages","(fr)","-AppleLocale","fr_FR"];app.launch();XCTAssertTrue(app.buttons["parents"].waitForExistence(timeout:6));shot("07-fr-city");app.buttons["city0"].swipeLeft();app.buttons["city2"].tap();shot("08-winter");XCUIDevice.shared.orientation = .landscapeLeft;shot("12-landscape");XCUIDevice.shared.orientation = .portrait;app.terminate()}
}
